/*
 * A140069  Triangle read by rows, n-th row = (n-1)-th power of the matrix X *
 *          [1,0,0,0,...]; where X = an infinite lower triangular bidiagonal
 *          matrix with [2,1,2,1,2,1,...] and [1,1,1,...] in the subdiagonal.
 * https://oeis.org/A140069
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   The triangle rows are generated by successively multiplying the
 *            previous row by the infinite lower‑triangular bidiagonal matrix
 *            X whose main diagonal alternates 2,1,2,1,… and whose subdiagonal
 *            is all 1. The flattened sequence a(n) is the triangle read
 *            left‑to‑right, row‑by‑row
 * Range:     u8 n <= 30, u16 n <= 66, u32 n <= 66, u64 n <= 66, u128 n <= 66,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>

seq_t a(idx_t n)
{
    /* The number of rows needed for n up to about 10000 is < 150.
       A static buffer of 200 rows is therefore plenty. */
    const size_t MAX_R = 200;
    seq_t rows[2][MAX_R];

    /* row 1 */
    rows[0][0] = (seq_t)1;
    size_t len = 1;            /* current row length */
    if (n == (idx_t)1) return rows[0][0];

    size_t pos = 1;            /* number of terms emitted so far */
    size_t cur = 0, nxt = 1;   /* indices of current and next buffer */

    for (size_t row = 2;; ++row) {
        /* generate next row of length len+1 */
        rows[nxt][0] = (seq_t)2 * rows[cur][0];

        for (size_t i = 1; i <= len; ++i) {
            seq_t v_prev = rows[cur][i - 1];
            seq_t v_curr = (i < len) ? rows[cur][i] : (seq_t)0;
            seq_t di     = (seq_t)(((i & 1) ? 1 : 2)); /* diag for column i+1 */
            rows[nxt][i] = v_prev + di * v_curr;
        }

        ++len;

        /* emit the new row's elements */
        for (size_t k = 0; k < len; ++k) {
            ++pos;
            if (pos == n)
                return rows[nxt][k];
        }

        /* prepare for next iteration */
        size_t tmp = cur;
        cur = nxt;
        nxt = tmp;
    }
}
